INSERT INTO livro (id_livro, titulo, sinopse, ano_publicacao, qnt_paginas, cd_editora, cd_autor) VALUES
(9788501012074, 'Cem Anos de Solidão', 'O romance narra a história da família Buendía ao longo de sete gerações na fictícia Macondo, vilarejo fundado por José Arcadio Buendía após uma longa jornada em busca de novas terras.
 
Guerras civis, amores proibidos, invenções fantásticas e uma solidão que parece perseguir a linhagem inteira se entrelaçam na saga, que mistura realidade e fantasia até o cumprimento de uma profecia escrita décadas antes pelo cigano Melquíades.', '1977-04-01', '448', 5, 5),
(9788501044457, 'O Diário de Anne Frank', 'Em 1942, a adolescente judia Anne Frank e sua família se escondem em um anexo secreto nos fundos de um prédio em Amsterdã para escapar da perseguição nazista. Ali, ela registra em seu diário o dia a dia do confinamento.

Durante mais de dois anos, Anne escreve sobre o medo, as brigas, os sonhos e as descobertas da juventude, deixando um dos testemunhos mais comoventes da Segunda Guerra Mundial.', '2019-01-01', '352', 5, 46),
(9788520918852, 'Grande Sertão: Veredas', 'O ex-jagunço Riobaldo relembra, em um longo monólogo, sua trajetória pelos sertões de Minas Gerais, as batalhas que travou e o intenso e conturbado vínculo que manteve com o companheiro Diadorim.
 
Escrito em uma linguagem inventiva que mistura o falar sertanejo com um vocabulário erudito, o romance mergulha nos dilemas do bem e do mal enquanto acompanha a saga dos jagunços pelo Brasil profundo.', '2012-10-01', '608', 20, 14),
(9788522031450, 'O Pequeno Príncipe', 'Um piloto cai com seu avião no deserto do Saara e, enquanto tenta consertar o motor, encontra um menino vindo de um pequeno asteroide distante. O garoto pede, insistentemente, que o piloto lhe desenhe um carneiro.
 
Aos poucos, o pequeno príncipe conta sobre seu planeta, sua rosa e as viagens que fez por outros mundos habitados por adultos estranhos e solitários, revelando reflexões simples e profundas sobre amizade, amor e aquilo que realmente importa na vida.', '2015-05-01', '96', 22, 3),
(9788525052247, 'Fahrenheit 451', 'Em um futuro em que os livros são proibidos, os bombeiros não apagam incêndios: sua função é queimar qualquer obra encontrada. Guy Montag é um deles e cumpre o trabalho sem questionar.

Depois de conhecer a jovem Clarisse e presenciar uma mulher que prefere morrer com sua biblioteca, Montag passa a esconder livros em casa e a duvidar de uma sociedade anestesiada por telas e entretenimento vazio.', '2012-01-01', '216', 6, 45),
(9788532503251, 'O Alquimista', 'Santiago, um jovem pastor andaluz, sonha repetidamente com um tesouro escondido perto das pirâmides do Egito. Decidido a descobrir o que o sonho significa, ele vende suas ovelhas e parte em uma longa jornada pelo deserto.
 
Pelo caminho, encontra um rei, uma cigana, um inglês estudioso e, por fim, um alquimista, que o ajudam a decifrar os sinais do universo. Juntos, eles conduzem Santiago a compreender o verdadeiro significado de sua Lenda Pessoal.', '2003-01-01', '222', 2, 4),
(9788532508126, 'A Hora da Estrela', 'O narrador Rodrigo S.M. conta a história de Macabéa, uma jovem nordestina pobre, datilógrafa desajeitada e quase invisível, que vive sozinha na cidade grande sem nunca ter tido a chance de sonhar com algo melhor.
 
Por meio de uma prosa que mistura compaixão e ironia, Clarice Lispector transforma a vida simples e apagada de Macabéa em uma reflexão sobre a miséria, a linguagem e o próprio ato de escrever.', '1998-08-04', '88', 2, 15),
(9788532511010, 'Harry Potter e a Pedra Filosofal', 'Órfão criado pelos tios que o desprezam, Harry Potter descobre em seu 11º aniversário que é um bruxo e recebe uma carta de aceitação em Hogwarts, a Escola de Magia e Bruxaria.
 
Na escola, ele faz amigos como Rony e Hermione, aprende feitiços e o esporte das vassouras voadoras, e se vê envolvido em um mistério que gira em torno da lendária Pedra Filosofal e do possível retorno do bruxo das trevas que matou seus pais.', '2000-04-07', '264', 2, 9),
(9788532511669, 'Harry Potter e a Câmara Secreta', 'Depois de férias difíceis na casa dos tios, Harry volta para o segundo ano em Hogwarts, apesar dos avisos do elfo doméstico Dobby de que algo terrível está para acontecer na escola.

Quando alunos começam a aparecer petrificados e mensagens escritas nas paredes anunciam a reabertura da Câmara Secreta, Harry, Rony e Hermione precisam descobrir quem é o herdeiro de Sonserina e que criatura se esconde no castelo.', '2000-01-01', '288', 2, 9),
(9788532512062, 'Harry Potter e o Prisioneiro de Azkaban', 'No terceiro ano em Hogwarts, Harry descobre que Sirius Black, um perigoso prisioneiro, fugiu da fortaleza de Azkaban e estaria atrás dele. Para proteger a escola, os assustadores dementadores passam a guardar seus portões.

Com a ajuda do professor Lupin, Harry aprende a enfrentar seus medos e, ao lado de Rony e Hermione, acaba descobrindo a verdade sobre o passado de seus pais e sobre o homem que todos acreditam ser um traidor.', '2000-01-01', '348', 2, 9),
(9788532512529, 'Harry Potter e o Cálice de Fogo', 'Hogwarts recebe o Torneio Tribruxo, uma competição entre três escolas de magia reservada a alunos mais velhos. Misteriosamente, o Cálice de Fogo escolhe Harry como um quarto campeão, mesmo sem ele ter se inscrito.

Obrigado a enfrentar dragões, criaturas aquáticas e um labirinto cheio de armadilhas, Harry percebe que alguém o colocou ali de propósito, em um plano que culmina no retorno de seu maior inimigo.', '2001-01-01', '584', 2, 9),
(9788532516220, 'Harry Potter e a Ordem da Fênix', 'Depois de testemunhar o retorno de Voldemort, Harry volta a Hogwarts e descobre que o Ministério da Magia nega tudo e trata ele e Dumbledore como mentirosos. A escola passa a ser controlada pela cruel professora Dolores Umbridge.
 
Impedidos de aprender a se defender, Harry e os amigos formam em segredo a Armada de Dumbledore, enquanto sonhos perturbadores o conduzem a uma profecia guardada no Departamento de Mistérios.', '2003-01-01', '704', 2, 9),
(9788532519474, 'Harry Potter e o Enigma do Príncipe', 'Com o mundo bruxo em guerra aberta, Harry começa o sexto ano em Hogwarts e encontra um velho livro de Poções cheio de anotações de alguém que se chama de Príncipe Mestiço, cujas dicas o tornam o melhor aluno da turma.
 
Em aulas particulares com Dumbledore, ele mergulha nas memórias do passado de Voldemort e descobre o segredo que mantém o bruxo das trevas vivo, enquanto suspeita de que Draco Malfoy trama algo dentro do castelo.', '2005-01-01', '512', 2, 9),
(9788532520661, 'O Conto da Aia', 'Na República de Gilead, regime teocrático que tomou o lugar dos Estados Unidos, as mulheres perderam todos os direitos. Offred é uma aia, obrigada a gerar filhos para um comandante e sua esposa.

Vigiada o tempo todo, ela relembra a vida que tinha antes, com o marido e a filha, e procura pequenas brechas de resistência em um sistema que controla corpos, palavras e pensamentos.', '2017-01-01', '368', 2, 42),
(9788532522610, 'Harry Potter e as Relíquias da Morte', 'Harry, Rony e Hermione deixam Hogwarts para cumprir a missão deixada por Dumbledore: encontrar e destruir as Horcruxes que garantem a imortalidade de Voldemort, enquanto o Ministério cai nas mãos dos Comensais da Morte.
 
Fugindo e sem saber em quem confiar, os três descobrem a lenda das Relíquias da Morte e seguem até o confronto final, na batalha que decide o destino do mundo bruxo dentro dos muros de Hogwarts.', '2007-01-01', '592', 2, 9),
(9788535911121, 'O Menino do Pijama Listrado', 'Bruno, um menino alemão de nove anos, se muda com a família para uma região isolada por causa do novo trabalho do pai e passa a observar, intrigado, um grupo de pessoas de pijama listrado do outro lado de uma cerca.
 
Ao fazer amizade com Shmuel, um garoto judeu preso do outro lado da cerca, Bruno vai descobrindo, sem entender completamente, o horror do Holocausto que envolve sua própria família.', '2007-10-11', '192', 1, 20),
(9788535911695, 'Capitães da Areia', 'Em Salvador, um grupo de meninos abandonados vive em um velho trapiche à beira do cais e sobrevive de pequenos furtos pelas ruas da cidade. Liderados por Pedro Bala, eles são conhecidos e temidos como os Capitães da Areia.

Entre a perseguição da polícia, a fome e a falta de afeto, cada garoto carrega seus próprios sonhos e feridas. Jorge Amado acompanha o bando com olhar humano, mostrando a infância roubada e a solidariedade que nasce entre eles.', '2008-01-01', '296', 1, 28),
(9788535914849, '1984', 'Em uma Londres governada por Oceania, Winston Smith trabalha no Ministério da Verdade reescrevendo a história para que ela sempre corresponda à versão oficial do Partido. Vigiado dia e noite pelas telas do Grande Irmão, ele começa a questionar em segredo o regime que domina cada aspecto de sua vida.
 
Ao se envolver com Julia e buscar pequenos espaços de liberdade e verdade, Winston arrisca tudo em um mundo onde até os pensamentos podem ser crime. Sua rebelião silenciosa o leva a um confronto direto com o Partido e com os limites do que a mente humana pode suportar.', '2009-07-21', '416', 1, 1),
(9788535918502, 'Hibisco Roxo', 'Kambili tem quinze anos e vive em uma casa rica na Nigéria, sob as regras rígidas do pai, Eugene, um empresário respeitado e católico fervoroso que pune a família com violência a cada pequeno desvio.
 
Quando ela e o irmão Jaja passam uma temporada na casa da tia Ifeoma, em Nsukka, descobrem um lar mais pobre, porém cheio de risos, discussões e liberdade, e começam a questionar o silêncio em que foram criados.', '2011-01-01', '328', 1, 48),
(9788535924732, 'Americanah', 'Ifemelu e Obinze se apaixonam ainda adolescentes em Lagos, mas a Nigéria dos anos 1990, sob ditadura militar, oferece pouco futuro. Ela parte para estudar nos Estados Unidos, onde pela primeira vez se descobre vista como negra.
 
Enquanto Ifemelu se torna uma blogueira conhecida por escrever sobre raça, Obinze tenta a vida como imigrante ilegal em Londres. Anos depois, os dois se reencontram em uma Nigéria transformada e precisam decidir o que resta daquele amor.', '2014-01-01', '520', 1, 48),
(9788535925470, 'Sejamos Todos Feministas', 'Adaptado de uma palestra que Chimamanda Ngozi Adichie fez em 2012, o ensaio parte de histórias da infância e da vida adulta da autora na Nigéria para mostrar como a desigualdade entre homens e mulheres está presente no cotidiano.
 
Com humor e clareza, ela discute o que significa ser feminista hoje e defende que a mudança começa na forma como criamos meninas e meninos, para que todos possam ser mais livres e mais fiéis a si mesmos.', '2015-01-01', '64', 1, 48),
(9788535928198, 'Homo Deus: Uma Breve História do Amanhã', 'Depois de investigar o passado da espécie em Sapiens, Harari volta o olhar para o futuro. Com a fome, as pestes e as guerras cada vez mais controladas, ele pergunta quais serão os próximos grandes projetos da humanidade.

O livro discute a busca pela imortalidade, pela felicidade e por poderes quase divinos, e examina como a inteligência artificial e a biotecnologia podem transformar o trabalho, a política e a própria ideia do que significa ser humano.', '2016-11-11', '448', 1, 7),
(9788535928839, 'A Insustentável Leveza do Ser', 'Em Praga, às vésperas da invasão soviética de 1968, o cirurgião Tomas divide sua vida entre o amor por Tereza e as muitas amantes de que não consegue abrir mão, entre elas a pintora Sabina.

Com a ocupação do país, os destinos dos personagens se dispersam entre o exílio e a volta para casa. Kundera mistura romance e reflexão filosófica para discutir o peso e a leveza das escolhas, o amor, a traição e a liberdade.', '2017-01-01', '344', 1, 31),
(9788535929225, 'Anna Kariênina', 'Casada com um alto funcionário do governo russo, Anna Kariênina leva uma vida respeitável em São Petersburgo até conhecer o conde Vrónski, um jovem oficial por quem se apaixona perdidamente. Ao assumir esse amor, ela desafia as convenções da aristocracia.

Em paralelo, o romance acompanha Liévin, um proprietário rural que busca sentido na vida do campo, na fé e no casamento. Tolstói entrelaça as duas histórias em um amplo retrato da sociedade russa do século XIX.', '2017-01-01', '808', 1, 30),
(9788535929881, 'Cosmos', 'Carl Sagan conduz o leitor por uma viagem que vai das origens do universo ao surgimento da vida na Terra, passando pelas estrelas, pelos planetas e pela possibilidade de existirem outras civilizações.
 
Escrito em linguagem acessível, o livro também conta a história das descobertas científicas e de seus personagens, mostrando como a curiosidade humana transformou nossa compreensão do lugar que ocupamos no espaço e no tempo.', '2017-01-01', '488', 1, 49),
(9788535930047, 'Guerra e Paz', 'Entre 1805 e 1812, enquanto os exércitos de Napoleão avançam sobre a Rússia, o romance acompanha a vida de cinco famílias aristocráticas, entre bailes, intrigas, casamentos e campos de batalha.
 
No centro da narrativa estão o desajeitado Pierre Bezúkhov, o orgulhoso príncipe Andrei Bolkónski e a jovem Natacha Rostova, cujos destinos se cruzam em uma obra monumental sobre a história, o acaso e o sentido da vida.', '2017-01-01', '1544', 1, 30),
(9788535930917, '21 Lições para o Século 21', 'Neste livro, Harari se concentra no presente e nas questões mais urgentes do nosso tempo, como o avanço da tecnologia, a crise da democracia liberal, o terrorismo, as notícias falsas e as mudanças climáticas.

Dividido em vinte e um capítulos temáticos, o autor convida o leitor a pensar com clareza em um mundo inundado de informações irrelevantes, discutindo trabalho, educação, religião, imigração e o sentido da vida.', '2018-01-01', '432', 1, 7),
(9788535933390, 'O Avesso da Pele', 'Depois que seu pai, Henrique, um professor de escola pública, é morto em uma abordagem policial desastrosa em Porto Alegre, Pedro decide reconstruir a história dele a partir de objetos, lembranças e relatos.
 
Ao refazer os passos do pai, o jovem revisita os relacionamentos da família e as marcas deixadas pelo racismo, em um romance sobre identidade, afeto e as feridas de um país que ainda não acertou as contas com o passado.', '2020-01-01', '192', 1, 51),
(9788535933925, 'Sapiens: Uma Breve História da Humanidade', 'Harari percorre a trajetória da espécie humana desde o surgimento do Homo sapiens na África, passando pela Revolução Cognitiva, que deu origem à linguagem, aos mitos e à capacidade de cooperação em larga escala.
 
O livro segue pela Revolução Agrícola e pela unificação da humanidade por meio de impérios, religiões e do dinheiro, até chegar à Revolução Científica e aos dilemas éticos que a tecnologia impõe ao futuro da nossa espécie.', '2020-11-13', '472', 1, 7),
(9788539003839, 'Rápido e Devagar: Duas Formas de Pensar', 'O psicólogo Daniel Kahneman, vencedor do Nobel de Economia, apresenta os dois sistemas que comandam o nosso pensamento: um rápido, intuitivo e emocional, e outro lento, deliberado e lógico.

Com base em décadas de pesquisa, ele mostra como atalhos mentais e vieses influenciam nossos julgamentos sem que percebamos, e como entender esses mecanismos ajuda a tomar decisões melhores na vida pessoal e profissional.', '2012-01-01', '608', 7, 32),
(9788539004119, 'O Poder do Hábito', 'O jornalista Charles Duhigg investiga a ciência por trás da formação dos hábitos, explicando como eles funcionam no cérebro e por que exercem tanto controle sobre nosso comportamento no dia a dia.
 
Por meio de exemplos de indivíduos, empresas e sociedades, o livro mostra como é possível identificar o ciclo de deixa, rotina e recompensa que sustenta um hábito para transformá-lo de forma deliberada.', '2012-09-24', '408', 7, 23),
(9788547000240, 'Mindset: A Nova Psicologia do Sucesso', 'A psicóloga Carol Dweck, professora de Stanford, defende que o sucesso depende menos do talento e mais da forma como encaramos nossas próprias capacidades. Ela distingue dois tipos de mentalidade: a fixa e a de crescimento.

Com exemplos da escola, do esporte, dos negócios e dos relacionamentos, a autora mostra como quem acredita que pode se desenvolver lida melhor com desafios e fracassos, e como é possível cultivar essa atitude.', '2017-01-18', '312', 7, 33),
(9788547001261, 'A Lógica do Cisne Negro', 'Taleb chama de Cisne Negro o evento altamente improvável, de enorme impacto, que só depois de acontecer parece explicável. Crises financeiras, grandes invenções e viradas históricas seriam exemplos desse fenômeno.
 
O livro mostra como a mente humana insiste em enxergar padrões e fazer previsões onde elas não são possíveis, e discute como lidar melhor com aquilo que não sabemos e não conseguimos antecipar.', '2021-01-01', '528', 7, 57),
(9788551002001, 'Tartarugas Até Lá Embaixo', 'Aza Holmes tem dezesseis anos e convive com um transtorno de ansiedade que a prende em espirais de pensamentos dos quais não consegue escapar. Quando um bilionário da cidade desaparece, sua melhor amiga, Daisy, a convence a investigar o caso.
 
A busca reaproxima Aza de Davis, filho do desaparecido e seu amigo de infância. Entre a amizade, o primeiro amor e a luta contra a própria mente, ela tenta descobrir quem realmente é.', '2017-01-01', '272', 3, 43),
(9788551002735, 'Me Chame pelo Seu Nome', 'Elio tem dezessete anos e passa os verões na casa da família, no litoral da Itália. Todo ano seu pai, professor universitário, recebe um jovem pesquisador como hóspede, e desta vez chega o americano Oliver.
 
Ao longo de seis semanas, a curiosidade de Elio se transforma em fascínio e depois em uma paixão intensa e correspondida. O romance acompanha a descoberta do desejo e a marca que esse verão deixa na vida dos dois.', '2018-01-01', '288', 3, 60),
(9788563560032, 'O Príncipe', 'Escrito em 1513 e dedicado a Lourenço de Médici, o tratado de Maquiavel analisa como os governantes conquistam, mantêm e perdem o poder, a partir da observação da política italiana de seu tempo e de exemplos da Antiguidade.

Ao separar a política da moral tradicional, o autor discute virtude, fortuna, crueldade e clemência com um realismo que escandalizou gerações e fez da obra um dos textos fundadores do pensamento político moderno.', '2010-07-22', '176', 21, 36),
(9788563560155, 'Orgulho e Preconceito', 'Elizabeth Bennet, a segunda de cinco irmãs de uma família da pequena nobreza inglesa, se choca com a arrogância do rico Fitzwilliam Darcy logo no primeiro encontro entre os dois.
 
Ao longo de uma sucessão de mal-entendidos, cartas reveladoras e reviravoltas sociais, os dois precisam superar o orgulho e os preconceitos que os separam para reconhecer o que realmente sentem um pelo outro.', '2011-06-21', '576', 21, 10),
(9788563560179, 'Triste Fim de Policarpo Quaresma', 'O major Policarpo Quaresma, funcionário público do Rio de Janeiro no início da República, é um patriota exaltado que estuda tudo sobre o Brasil e chega a propor que o tupi seja adotado como língua oficial.

Ridicularizado por suas ideias, ele tenta transformar o país pela agricultura e depois pela política, mas esbarra na burocracia, na corrupção e no autoritarismo. Lima Barreto faz uma sátira amarga do nacionalismo ingênuo.', '2011-01-01', '368', 21, 41),
(9788563560278, 'Odisseia', 'Terminada a Guerra de Troia, o herói Ulisses tenta voltar para sua ilha de Ítaca, mas enfrenta dez anos de viagem marcados por tempestades, monstros, feiticeiras e a ira dos deuses.

Enquanto isso, sua esposa Penélope resiste aos pretendentes que ocupam o palácio, e seu filho Telêmaco parte em busca de notícias do pai. O poema de Homero é uma das narrativas fundadoras da literatura ocidental.', '2011-01-01', '576', 21, 38),
(9788563560292, 'O Grande Gatsby', 'No verão de 1922, Nick Carraway se muda para Long Island e passa a ser vizinho de Jay Gatsby, um milionário misterioso conhecido pelas festas extravagantes que oferece em sua mansão.

Aos poucos, Nick descobre que todo aquele luxo tem um único objetivo: reconquistar Daisy Buchanan, um amor do passado agora casada com outro homem. A obsessão de Gatsby expõe o vazio e as ilusões por trás do sonho americano.', '2011-09-30', '256', 21, 35),
(9788563560315, 'Madame Bovary', 'Criada entre leituras românticas, Emma se casa com o médico Charles Bovary esperando uma vida de paixão e luxo, mas encontra apenas a rotina monótona de uma pequena cidade do interior da França.
 
Entediada e frustrada, ela busca nos amantes e nas compras a existência que imaginou, acumulando mentiras e dívidas que a levam à ruína. Flaubert retrata com precisão o choque entre o sonho e a realidade.', '2011-01-01', '496', 21, 56),
(9788563560438, 'O Retrato de Dorian Gray', 'Encantado com a própria beleza após ver seu retrato recém-pintado, o jovem Dorian Gray deseja permanecer eternamente jovem, mesmo que isso custe sua alma, enquanto o quadro envelhece e registra seus pecados em seu lugar.
 
Livre das marcas físicas de seus atos, Dorian mergulha em uma vida de excessos e crueldade, enquanto o retrato escondido revela, cada vez mais monstruoso, a verdadeira face de sua corrupção moral.', '2012-04-12', '264', 21, 22),
(9788563560476, 'Grandes Esperanças', 'Órfão criado pela irmã e pelo cunhado ferreiro, o menino Pip ajuda um fugitivo da prisão e, pouco depois, passa a frequentar a casa da excêntrica srta. Havisham, onde se apaixona pela fria e bela Estella.
 
Anos mais tarde, um benfeitor anônimo lhe oferece uma fortuna e a chance de se tornar um cavalheiro em Londres. Ao descobrir de onde vem o dinheiro, Pip é obrigado a rever tudo o que pensava sobre riqueza, gratidão e caráter.', '2012-01-01', '704', 21, 54),
(9788563560490, 'Razão e Sensibilidade', 'Com a morte do pai, as irmãs Elinor e Marianne Dashwood perdem a casa e a fortuna da família e precisam se mudar com a mãe para um chalé modesto no interior da Inglaterra.
 
Elinor, sensata e contida, esconde o que sente por Edward Ferrars, enquanto a impulsiva Marianne se entrega sem reservas à paixão pelo sedutor Willoughby. As desilusões de ambas mostram os riscos de viver só pela razão ou só pelo sentimento.', '2012-01-01', '512', 21, 10),
(9788563560513, 'A Desobediência Civil', 'Em 1846, Henry David Thoreau passou uma noite na cadeia por se recusar a pagar impostos a um governo que mantinha a escravidão e promovia a guerra contra o México. Dessa experiência nasceu este ensaio.
 
O autor defende que o indivíduo tem o dever de não colaborar com leis que considera injustas, mesmo que isso lhe custe a liberdade. O texto inspirou movimentos de resistência pacífica no mundo inteiro.', '2012-01-01', '152', 21, 55),
(9788563560551, 'Dom Quixote', 'De tanto ler romances de cavalaria, um fidalgo da região da Mancha perde o juízo e decide se tornar cavaleiro andante. Com o nome de Dom Quixote, ele sai pelo mundo para defender os fracos e honrar sua amada Dulcineia.
 
Acompanhado do fiel e prático escudeiro Sancho Pança, ele confunde moinhos com gigantes e estalagens com castelos, em aventuras que misturam humor e melancolia e fundaram o romance moderno.', '2012-01-01', '1328', 21, 53),
(9788563560568, 'Ilíada', 'No décimo ano da Guerra de Troia, o herói Aquiles se desentende com o rei Agamêmnon e, ferido em sua honra, se recusa a continuar lutando ao lado dos gregos.
 
Sem seu maior guerreiro, o exército grego sofre derrotas sucessivas diante dos troianos liderados por Heitor. A morte de Pátroclo, amigo de Aquiles, faz o herói voltar ao combate movido por uma fúria que decide o rumo da guerra.', '2013-01-01', '720', 21, 38),
(9788566636239, 'Drácula', 'O jovem advogado Jonathan Harker viaja até a Transilvânia para fechar um negócio imobiliário com o misterioso Conde Drácula e logo descobre que está sendo mantido prisioneiro no castelo do nobre vampiro.
 
De volta à Inglaterra, Drácula espalha o terror pela Londres vitoriana, obrigando um pequeno grupo liderado pelo professor Van Helsing a se unir para caçá-lo antes que ele transforme suas vítimas em criaturas da noite.', '2018-10-24', '580', 15, 26),
(9788571646858, 'A Metamorfose', 'Certa manhã, o caixeiro-viajante Gregor Samsa acorda em sua cama transformado em um inseto monstruoso, sem qualquer explicação para o que lhe aconteceu. Incapaz de sair para o trabalho, ele precisa lidar com as consequências imediatas dessa mudança.
 
Preso ao próprio quarto, Gregor passa a enfrentar o horror, a vergonha e, aos poucos, a rejeição da própria família, numa narrativa que expõe a alienação do indivíduo diante do trabalho e dos laços familiares.', '1997-08-07', '96', 1, 6),
(9788578270889, 'O Leão, a Feiticeira e o Guarda-Roupa', 'Os quatro irmãos Pevensie são enviados para o interior da Inglaterra durante a guerra e, ao explorarem a casa onde estão hospedados, descobrem que um velho guarda-roupa é a passagem para o mundo mágico de Nárnia.
 
Lá, eles se veem no meio de uma batalha entre o bem e o mal, ao lado do grande leão Aslam, contra o domínio gelado e cruel da Feiticeira Branca, que mantém Nárnia presa em um inverno eterno.', '2009-09-22', '184', 16, 27),
(9788579800863, 'A Esperança', 'Depois de sobreviver duas vezes à arena, Katniss Everdeen é levada ao Distrito 13, que todos acreditavam destruído, e aceita se tornar o Tordo, símbolo da rebelião contra a Capital.

Enquanto a guerra se espalha por Panem e Peeta permanece prisioneiro do presidente Snow, Katniss descobre que os líderes rebeldes também têm seus próprios interesses e precisa decidir em quem pode confiar.', '2012-01-01', '424', 2, 12),
(9788580410327, 'O Temor do Sábio', 'No segundo dia de sua narrativa, Kvothe continua a contar sua história ao cronista. Ainda estudante na Universidade e perseguido pela rivalidade com um nobre poderoso, ele é obrigado a se afastar e partir para terras distantes.
 
A serviço de um governante em Vintas, ele caça bandidos na floresta, cruza com uma criatura lendária do mundo das fadas e treina com os guerreiros ademrianos, enquanto segue as pistas do grupo que matou sua família.', '2011-01-01', '960', 10, 47),
(9788580572261, 'A Culpa é das Estrelas', 'Hazel Grace tem dezesseis anos e convive com um câncer que a obriga a carregar um cilindro de oxigênio para onde vai. Em um grupo de apoio, ela conhece Augustus Waters, um ex-jogador de basquete em remissão.

Unidos pelo humor e por um livro que ambos adoram, os dois vivem uma história de amor intensa, que os leva até Amsterdã em busca do autor da obra e os faz refletir sobre a vida, a perda e o que deixamos para trás.', '2014-01-01', '288', 3, 43),
(9788580572902, 'Garota Exemplar', 'Na manhã de seu quinto aniversário de casamento, Amy Dunne desaparece de casa, deixando sinais de luta na sala. Todas as suspeitas recaem sobre o marido, Nick, cujo comportamento estranho só piora a situação.

Alternando a versão de Nick com os diários de Amy, o suspense revela aos poucos as mentiras e os ressentimentos de um casamento que parecia perfeito, até uma reviravolta que muda tudo o que o leitor acreditava saber.', '2013-01-01', '448', 3, 44),
(9788580573015, 'Extraordinário', 'August Pullman, um menino de dez anos nascido com uma rara condição genética que causa deformidades faciais, frequenta a escola regular pela primeira vez após anos sendo educado em casa.
 
Contada sob diferentes pontos de vista, a história acompanha como Auggie enfrenta o julgamento e a curiosidade dos colegas enquanto conquista, aos poucos, a aceitação e a amizade de quem o rodeia.', '2013-01-31', '320', 3, 24),
(9788580573152, 'O Teorema Katherine', 'Colin Singleton é um ex-menino prodígio com uma estranha particularidade: só namora garotas chamadas Katherine, e já levou um fora de dezenove delas. Depois do último, ele cai na estrada com o melhor amigo, Hassan.
 
Na pequena cidade de Gutshot, no Tennessee, Colin tenta criar um teorema matemático capaz de prever o futuro de qualquer relacionamento, e acaba descobrindo que nem tudo na vida cabe em uma fórmula.', '2013-01-01', '304', 3, 43),
(9788580573299, 'Como Eu Era Antes de Você', 'Louisa Clark, uma jovem de vinte e seis anos sem grandes ambições, é contratada para cuidar de Will Traynor, um ex-executivo bem-sucedido que ficou tetraplégico após um acidente e perdeu a vontade de viver.
 
Ao longo dos meses de convivência, os dois desenvolvem um vínculo intenso que faz Lou repensar sua própria vida, enquanto ela tenta convencer Will de que ainda vale a pena continuar.', '2013-01-01', '320', 3, 19),
(9788580573749, 'Cidades de Papel', 'Quentin Jacobsen sempre foi apaixonado por sua vizinha, a imprevisível Margo Roth Spiegelman. Certa noite, ela entra pela janela do quarto dele e o convoca para uma madrugada de vinganças pela cidade.

No dia seguinte, Margo desaparece, deixando apenas pistas espalhadas. Ao segui-las com os amigos, Quentin percebe que a garota que ele procurava talvez fosse bem diferente da que imaginava conhecer.', '2013-01-01', '368', 3, 43),
(9788580576467, 'Uma Breve História do Tempo', 'Stephen Hawking explica, em linguagem acessível a leigos, as grandes questões da física moderna: como o universo começou, se ele terá um fim, o que é o tempo e o que acontece dentro de um buraco negro.
 
Do modelo de Aristóteles à relatividade de Einstein e à mecânica quântica, o livro percorre as teorias que moldaram nossa visão do cosmos e a busca por uma explicação única para todas as forças da natureza.', '2015-01-01', '256', 3, 61),
(9788580578645, 'Depois de Você', 'Um ano e meio depois de perder Will Traynor, Louisa Clark trabalha em um bar de aeroporto em Londres e não consegue seguir em frente. Um acidente a obriga a voltar para a casa dos pais e a entrar em um grupo de apoio ao luto.
 
Enquanto se aproxima de Sam, o paramédico que a socorreu, Lou é surpreendida pela chegada de uma adolescente ligada ao passado de Will, que vira sua rotina de cabeça para baixo e a força a recomeçar.', '2016-01-01', '320', 3, 19),
(9788582850015, 'Memórias Póstumas de Brás Cubas', 'Já morto, Brás Cubas decide narrar sua própria biografia, dedicando o livro ao verme que roeu as frias carnes de seu cadáver, e revisita com ironia os fracassos amorosos e políticos de sua vida.
 
Por meio de capítulos curtos e de uma narrativa fragmentada e cheia de digressões, o defunto autor expõe, com humor ácido, a futilidade e a hipocrisia da elite brasileira do século XIX.', '2014-09-16', '368', 21, 2),
(9788582850145, 'Hamlet', 'O príncipe Hamlet volta à Dinamarca para o funeral do pai e encontra a mãe já casada com seu tio Cláudio, o novo rei. Certa noite, o fantasma do pai lhe revela que foi assassinado pelo irmão e exige vingança.
 
Dividido entre a dúvida e o dever, Hamlet se finge de louco para investigar a verdade, e sua hesitação desencadeia uma sequência de mortes que atinge todos ao seu redor na mais célebre tragédia de Shakespeare.', '2015-01-01', '320', 21, 52),
(9788582850350, 'Dom Casmurro', 'Já velho, Bento Santiago, o Bentinho, relembra a infância na Rua de Matacavalos e o amor que nutria pela vizinha Capitu, apesar da promessa feita por sua mãe de que ele se tornaria padre. Aos poucos, os dois driblam os obstáculos e conseguem se casar.
 
Anos depois, porém, a morte do amigo Escobar desperta em Bentinho um ciúme corrosivo. Ele passa a suspeitar de uma traição entre Capitu e o amigo, e o leitor é conduzido por uma narrativa ambígua, onde nunca fica claro se a culpa de Capitu é real ou fruto da mente atormentada do narrador.', '2016-07-26', '400', 21, 2),
(9788582850404, 'Romeu e Julieta', 'Em Verona, duas famílias poderosas, os Montéquio e os Capuleto, vivem em guerra há gerações. Em um baile de máscaras, o jovem Romeu Montéquio conhece Julieta Capuleto, e os dois se apaixonam à primeira vista.
 
Casados em segredo com a ajuda de frei Lourenço, eles tentam escapar do ódio que divide suas casas, mas uma sucessão de duelos, desencontros e mensagens perdidas conduz a história a um desfecho trágico.', '2016-01-01', '248', 21, 52),
(9788582850480, 'Os Miseráveis', 'Depois de cumprir dezenove anos de trabalhos forçados por ter roubado um pão, Jean Valjean sai da prisão marcado pela condenação. Um gesto de bondade de um bispo o leva a reconstruir a vida sob outro nome.

Perseguido sem trégua pelo inspetor Javert, ele cria a pequena Cosette em meio às convulsões da França do século XIX. Victor Hugo constrói um vasto painel sobre justiça, pobreza e redenção.', '2017-01-01', '1912', 21, 40),
(9788582850985, 'Mulherzinhas', 'Durante a Guerra Civil americana, as quatro irmãs March, Meg, Jo, Beth e Amy, enfrentam as dificuldades financeiras da família e a ausência do pai, servindo no front, apoiadas pela força e pelo exemplo da mãe.
 
Ao longo dos anos, cada uma das irmãs precisa lidar com seus próprios sonhos, perdas e amadurecimento, em uma história que celebra a união familiar e a busca pela independência feminina.', '2020-01-09', '592', 21, 25),
(9788594540188, 'Frankenstein', 'Obcecado por desvendar os segredos da vida, o jovem cientista Victor Frankenstein consegue dar vida a uma criatura montada a partir de partes de cadáveres, mas se horroriza com o resultado e a abandona.
 
Rejeitada por seu criador e por toda a sociedade, a criatura passa a buscar vingança contra Victor, desencadeando uma perseguição trágica que questiona os limites da ciência e da responsabilidade humana.', '2017-02-06', '304', 15, 21),
(9788595084377, 'O Silmarillion', 'Reunindo as lendas mais antigas do universo de Tolkien, o livro narra a criação do mundo pela música dos Ainur e os acontecimentos das primeiras eras, muito antes das aventuras de Bilbo e Frodo.

No centro da história estão as Silmarils, três joias forjadas pelo elfo Fëanor e roubadas por Morgoth, o primeiro Senhor do Escuro, o que desencadeia guerras, juramentos trágicos e a queda de reinos inteiros.', '2019-01-01', '496', 11, 13),
(9788595084742, 'O Hobbit', 'Bilbo Bolseiro é um hobbit que leva uma vida tranquila até receber a visita do mago Gandalf e de treze anões, que o arrastam para uma expedição rumo à Montanha Solitária, onde o dragão Smaug guarda um imenso tesouro.

Pelo caminho, Bilbo enfrenta trolls, orques e aranhas gigantes, e encontra um misterioso anel nas cavernas onde vive a criatura Gollum, descobrindo em si uma coragem que nem imaginava ter.', '2019-01-01', '336', 11, 13),
(9788595084759, 'O Senhor dos Anéis: A Sociedade do Anel', 'O hobbit Frodo Bolseiro herda de seu tio Bilbo um simples anel que se revela ser o Um Anel, capaz de dar a Sauron, o Senhor do Escuro, poder para dominar toda a Terra-média.
 
Para impedir essa ameaça, Frodo parte do Condado ao lado de uma sociedade formada por hobbits, elfos, anões e homens, com a missão de levar o anel até as Montanhas da Perdição e destruí-lo para sempre.', '2019-11-25', '576', 11, 13),
(9788595084766, 'O Senhor dos Anéis: As Duas Torres', 'Com a Sociedade do Anel desfeita, Frodo e Sam seguem sozinhos em direção a Mordor, guiados pela traiçoeira criatura Gollum, que já possuiu o anel e deseja recuperá-lo.

Enquanto isso, Aragorn, Legolas e Gimli partem em busca dos hobbits capturados e acabam envolvidos na defesa do reino de Rohan contra os exércitos do mago Saruman.', '2019-01-01', '464', 11, 13),
(9788595084773, 'O Senhor dos Anéis: O Retorno do Rei', 'As forças de Sauron marcham sobre Gondor, e os povos livres da Terra-média se reúnem para a batalha decisiva diante dos muros de Minas Tirith, enquanto Aragorn assume seu destino como herdeiro do trono.

Longe dali, exaustos e quase sem esperança, Frodo e Sam atravessam as terras de Mordor para tentar destruir o Um Anel nas chamas da Montanha da Perdição.', '2019-01-01', '528', 11, 13),
(9788598078175, 'A Menina que Roubava Livros', 'Narrada pela Morte, a história acompanha Liesel Meminger, uma menina alemã que, durante a Segunda Guerra Mundial, encontra consolo furtando livros e aprendendo a ler com a ajuda do pai adotivo.
 
Enquanto a família esconde um refugiado judeu no porão de casa, Liesel descobre no poder das palavras uma forma de resistência em meio ao horror e à destruição que tomam conta de sua cidade.', '2007-01-01', '480', 3, 18),
(9788598078397, 'Percy Jackson e o Ladrão de Raios', 'Aos doze anos, Percy Jackson descobre que é filho de Poseidon, o deus grego dos mares, e que seu mau desempenho na escola sempre teve uma explicação que ninguém lhe havia contado.
 
Acusado de roubar o raio mestre de Zeus, Percy parte em uma jornada ao lado de amigos semideuses para encontrar o verdadeiro culpado antes que uma guerra entre os deuses do Olimpo se torne inevitável.', '2008-11-21', '400', 3, 16),
(9788599296578, 'O Guia do Mochileiro das Galáxias', 'Momentos antes de a Terra ser destruída para dar lugar a uma via expressa hiperespacial, o inglês Arthur Dent é resgatado por seu amigo Ford Prefect, que na verdade é um alienígena disfarçado, pesquisador do Guia do Mochileiro das Galáxias.
 
Juntos, eles embarcam em uma jornada caótica pelo espaço, cruzando com personagens excêntricos e situações absurdas, sempre acompanhados do famoso guia interestelar e da enigmática resposta 42 para o sentido da vida, do universo e de tudo mais.', '2007-04-02', '208', 10, 8),
(9788599296585, 'O Restaurante no Fim do Universo', 'Depois de escapar da destruição da Terra, Arthur Dent, Ford Prefect, Zaphod Beeblebrox, Trillian e o deprimido robô Marvin continuam vagando pela galáxia a bordo da nave Coração de Ouro, e a fome aperta.
 
A solução é jantar no Milliways, o restaurante onde os clientes assistem ao fim do universo como espetáculo. Enquanto isso, Zaphod procura o homem que realmente governa tudo, e Arthur vai parar em um passado muito distante.', '2009-01-01', '240', 10, 8),
(9788599296592, 'A Vida, o Universo e Tudo Mais', 'Depois de anos perdido na Terra pré-histórica, Arthur Dent é resgatado por Ford Prefect com a ajuda de um sofá que surge do nada, e os dois vão parar no meio de uma partida de críquete na Inglaterra.
 
Lá eles descobrem que os habitantes do planeta Krikkit, incapazes de aceitar a existência do resto do universo, pretendem destruí-lo por completo, e cabe ao improvável grupo de viajantes impedir a catástrofe.', '2009-01-01', '224', 10, 8),
(9788599296608, 'Até Mais, e Obrigado pelos Peixes!', 'Depois de oito anos viajando pelo espaço, Arthur Dent volta para a Terra e a encontra intacta, como se nunca tivesse sido demolida. Todos se lembram apenas de uma estranha alucinação coletiva, e os golfinhos desapareceram.
 
Enquanto tenta entender o que aconteceu, Arthur se apaixona por Fenchurch, uma moça que também sente que algo está errado com o mundo, e os dois partem em busca da mensagem final de Deus para sua criação.', '2009-01-01', '208', 10, 8),
(9780061120084, 'To Kill a Mockingbird', 'Uma criança acompanha o julgamento que revela os conflitos raciais de uma pequena cidade do sul dos Estados Unidos.', '2006-01-01', 336, 23, 63),
(9780316769488, 'The Catcher in the Rye', 'Holden Caulfield percorre Nova York enquanto enfrenta o luto, a solidão e a dificuldade de crescer.', '1991-01-01', 277, 24, 64),
(9780743273565, 'The Great Gatsby', 'Um narrador observa a busca de Jay Gatsby por um amor antigo em meio ao luxo e às ilusões dos anos vinte.', '2004-01-01', 180, 25, 35),
(9780451524935, '1984', 'Um funcionário começa a questionar o regime que vigia a população e reescreve o passado.', '1950-01-01', 328, 26, 1),
(9780451526342, 'Animal Farm', 'Os animais de uma fazenda descobrem como a promessa de igualdade pode se transformar em outra forma de opressão.', '1996-01-01', '', 26, 1),
(9780060850524, 'Brave New World', 'Uma sociedade condicionada para a felicidade confronta pessoas que desejam liberdade e escolhas próprias.', '2006-01-01', 288, 23, 11),
(9781451673319, 'Fahrenheit 451', 'Um bombeiro encarregado de queimar livros começa a desconfiar do mundo que ajudou a manter.', '2012-01-01', 249, 27, 45),
(9780141439518, 'Pride and Prejudice', 'Elizabeth Bennet e Darcy precisam rever suas primeiras impressões em uma sociedade marcada por posição social e casamento.', '2003-01-01', 480, 28, 10),
(9780141439556, 'Wuthering Heights', 'O vínculo entre Catherine e Heathcliff deixa marcas que atravessam famílias e gerações.', '2003-01-01', 416, 28, 17),
(9780141441146, 'Jane Eyre', 'Uma jovem governanta procura independência e afeto enquanto enfrenta os segredos de uma propriedade isolada.', '2006-01-01', 624, 28, 39),
(9780141439600, 'A Tale of Two Cities', 'Destinos ingleses e franceses se cruzam durante os conflitos da Revolução Francesa.', '2003-01-01', 544, 28, 54),
(9780141439563, 'Great Expectations', 'Pip acredita que a ascensão social resolverá seus problemas, mas precisa compreender a origem de sua fortuna.', '2003-01-01', 544, 28, 54),
(9780141439570, 'The Picture of Dorian Gray', 'Um retrato passa a registrar a deterioração moral de um homem que conserva a aparência jovem.', '2003-01-01', 304, 28, 22),
(9780141439471, 'Frankenstein', 'Um cientista dá vida a uma criatura e abandona a responsabilidade pelas consequências de sua descoberta.', '2003-01-01', '', 28, 21),
(9780141439587, 'Emma', 'Uma jovem confiante em seu talento para unir casais descobre os limites de suas interpretações sobre os outros.', '2003-01-01', 512, 28, 10),
(9780141439662, 'Sense and Sensibility', 'Duas irmãs com temperamentos distintos enfrentam perdas financeiras e as incertezas do amor.', '2003-01-01', '', 28, 10),
(9780547928227, 'The Hobbit', 'Bilbo deixa a tranquilidade do Condado para ajudar anões a recuperar um reino guardado por um dragão.', '2012-01-01', 300, 29, 13),
(9780547928210, 'The Fellowship of the Ring', 'Frodo e seus companheiros iniciam uma viagem para impedir que um anel de poder retorne ao seu criador.', '2012-01-01', 432, 29, 13),
(9780547928203, 'The Two Towers', 'A sociedade se divide enquanto a guerra avança e os portadores do anel se aproximam de Mordor.', '2012-01-01', 352, 29, 13),
(9780547928197, 'The Return of the King', 'A guerra pela Terra-média chega à sua decisão enquanto a missão do anel enfrenta seu maior obstáculo.', '2012-01-01', 432, 29, 13),
(9780590353427, 'Harry Potter and the Sorcerer''s Stone', 'Um menino descobre que é bruxo e encontra amizade, estudo e um mistério em sua nova escola.', '1999-01-01', 309, 30, 9),
(9780439064873, 'Harry Potter and the Chamber of Secrets', 'Mensagens ameaçadoras e ataques em Hogwarts conduzem Harry a um segredo antigo da escola.', '2000-01-01', 341, 30, 9),
(9780439136365, 'Harry Potter and the Prisoner of Azkaban', 'A fuga de um prisioneiro força Harry a reconsiderar o passado de sua família.', '2001-01-01', 435, 30, 9),
(9780439139601, 'Harry Potter and the Goblet of Fire', 'Selecionado para um torneio perigoso, Harry enfrenta provas que escondem um plano maior.', '2002-01-01', 734, 30, 9),
(9780439358071, 'Harry Potter and the Order of the Phoenix', 'Harry reúne colegas para aprender defesa enquanto o mundo mágico se recusa a reconhecer uma ameaça.', '2004-01-01', 870, 30, 9),
(9780439785969, 'Harry Potter and the Half-Blood Prince', 'Lições sobre o passado de Voldemort ajudam Harry a preparar uma missão decisiva.', '2006-01-01', 652, 30, 9),
(9780545010221, 'Harry Potter and the Deathly Hallows', 'Harry, Rony e Hermione deixam a escola em busca dos objetos que sustentam o poder de Voldemort.', '2007-01-01', 759, 30, 9),
(9780439023528, 'The Hunger Games', 'Katniss se oferece para substituir a irmã em uma competição mortal transmitida para toda a nação.', '2010-01-01', 374, 31, 12),
(9780439023498, 'Catching Fire', 'A sobrevivência de Katniss se torna símbolo de resistência e provoca uma nova reação da Capital.', '2009-01-01', 391, 31, 12),
(9780439023511, 'Mockingjay', 'Transformada em símbolo da revolta, Katniss procura um caminho próprio em meio à guerra.', '2010-01-01', 390, 31, 12),
(9780062024039, 'Divergent', 'Uma jovem precisa esconder características que desafiam a divisão rígida de sua sociedade em facções.', '2012-01-01', '', 32, 65),
(9780062024046, 'Insurgent', 'Tris enfrenta alianças instáveis e escolhas difíceis depois da ruptura entre as facções.', '2012-01-01', '', 32, 65),
(9780062024060, 'Allegiant', 'A descoberta do mundo além da cidade leva Tris a questionar a história em que cresceu.', '2013-01-01', '', 32, 65),
(9780316015844, 'Twilight', 'Bella se aproxima de um colega misterioso e descobre o perigo por trás de sua identidade.', '2006-01-01', 498, 33, 66),
(9780316160193, 'New Moon', 'A partida de Edward leva Bella a buscar novos vínculos e enfrentar riscos inesperados.', '2006-01-01', 563, 33, 66),
(9780316160209, 'Eclipse', 'Uma ameaça em Seattle obriga grupos rivais a cooperar enquanto Bella toma decisões sobre seu futuro.', '2007-01-01', 629, 33, 66),
(9780316067928, 'Breaking Dawn', 'As escolhas de Bella mudam sua vida e colocam os Cullen diante de um confronto com as autoridades vampíricas.', '2008-01-01', 756, 33, 66),
(9780142402511, 'Looking for Alaska', 'Um estudante de internato encontra amizade e paixão e precisa lidar com perguntas deixadas por uma perda.', '2006-01-01', 221, 34, 43),
(9780525478812, 'The Fault in Our Stars', 'Dois adolescentes se conhecem em um grupo de apoio e constroem uma relação entre viagens, leituras e incertezas.', '2012-01-01', 313, 35, 43),
(9780142414934, 'Paper Towns', 'O desaparecimento de uma colega leva Quentin a seguir pistas e revisar a imagem idealizada que fazia dela.', '2009-01-01', 305, 34, 43),
(9780375831003, 'The Book Thief', 'Uma menina encontra nos livros uma forma de resistência durante a Alemanha nazista.', '2006-01-01', 552, 36, 18),
(9780385751537, 'The Boy in the Striped Pajamas', 'A amizade entre duas crianças expõe a violência de um campo de concentração por uma perspectiva infantil.', '2007-01-01', 216, 37, 20),
(9780553418026, 'The Martian', 'Abandonado em Marte após um acidente, um astronauta usa ciência e criatividade para tentar sobreviver.', '2014-01-01', '', 38, 67),
(9780307887443, 'Ready Player One', 'Um jovem participa de uma disputa virtual por pistas que podem mudar o controle de um universo digital.', '2011-01-01', '', 39, 68),
(9780345391803, 'The Hitchhiker''s Guide to the Galaxy', 'Arthur Dent escapa da destruição da Terra e percorre o espaço ao lado de companheiros improváveis.', '1995-01-01', 224, 40, 8),
(9780441172719, 'Dune', 'Paul Atreides chega a um planeta desértico onde recursos, religião e poder político se entrelaçam.', '1990-01-01', 896, 41, 69),
(9780553593716, 'A Game of Thrones', 'Famílias nobres disputam o trono enquanto ameaças antigas retornam às fronteiras do reino.', '2011-01-01', 864, 42, 70),
(9780553573404, 'A Clash of Kings', 'Vários pretendentes disputam o poder e transformam alianças familiares em uma guerra de sucessão.', '2000-01-01', 1008, 42, 70),
(9780553573428, 'A Storm of Swords', 'A guerra altera os destinos das casas de Westeros e torna cada promessa um possível risco.', '2003-01-01', 1216, 42, 70),
(9780553582024, 'A Feast for Crows', 'Depois de grandes conflitos, sobreviventes buscam consolidar poder em um reino fragmentado.', '2006-01-01', 1104, 42, 70),
(9780553582017, 'A Dance with Dragons', 'Disputas no Norte e além do mar complicam os projetos de governantes e exilados.', '2013-01-01', 1152, 42, 70),
(9780756404741, 'The Name of the Wind', 'Kvothe relata sua juventude entre uma trupe, as ruas e uma universidade de conhecimentos perigosos.', '2008-01-01', 736, 43, 47),
(9780756407919, 'The Wise Man''s Fear', 'A formação de Kvothe continua em viagens que ampliam sua reputação e seus conflitos.', '2012-01-01', 1120, 43, 47),
(9780765326355, 'The Way of Kings', 'Soldados, estudiosos e líderes tentam compreender um mundo dividido por guerras e tempestades.', '2010-01-01', 1007, 44, 71),
(9780765377135, 'Words of Radiance', 'Novos poderes e antigas ordens mudam os caminhos de personagens envolvidos na guerra das Planícies Partidas.', '2015-01-01', '', 44, 71),
(9780765311788, 'Mistborn: The Final Empire', 'Uma jovem com poderes metálicos se une a uma equipe que planeja derrubar um império aparentemente invencível.', '2006-01-01', 541, 44, 71),
(9780062059932, 'American Gods', 'Um ex-presidiário cruza os Estados Unidos ao lado de uma figura que o envolve em uma disputa entre deuses.', '2011-01-01', '', 45, 72),
(9780062472106, 'Good Omens', 'Um anjo e um demônio tentam evitar o fim do mundo enquanto procuram um menino que pode desencadeá-lo.', '2019-01-01', '', 45, 73),
(9780061122415, 'The Alchemist', 'Um pastor parte em busca de um tesouro e aprende a interpretar os encontros e sinais de sua viagem.', '2006-01-01', 208, 46, 4),
(9780060883287, 'One Hundred Years of Solitude', 'As gerações da família Buendía atravessam amores, guerras e solidão na cidade de Macondo.', '2006-01-01', '', 23, 5),
(9780307389732, 'Love in the Time of Cholera', 'Um amor de juventude reaparece após décadas e transforma a velhice de dois personagens.', '2007-01-01', 348, 47, 5),
(9780679720201, 'The Stranger', 'Um homem de aparente indiferença é julgado por um crime e pelas expectativas sociais sobre seus sentimentos.', '1989-01-01', 123, 48, 74),
(9780679734529, 'The Brothers Karamazov', 'Um conflito familiar conduz três irmãos a discussões sobre responsabilidade, fé e liberdade.', '1991-01-01', 796, 49, 75),
(9780679734505, 'Crime and Punishment', 'Um estudante comete um assassinato e passa a enfrentar as consequências morais de sua justificativa intelectual.', '1993-01-01', '', 49, 75),
(9780140449266, 'The Count of Monte Cristo', 'Preso por uma conspiração, Edmond Dantès reconstrói sua identidade e organiza um elaborado plano de vingança.', '2003-01-01', 1312, 28, 76),
(9780140445923, 'The Iliad', 'A ira de Aquiles e as perdas da guerra de Troia expõem os limites da honra e da violência.', '1998-01-01', '', 28, 38),
(9780140449334, 'Meditations', 'Reflexões pessoais de um imperador discutem disciplina, convivência e aceitação das mudanças da vida.', '2006-01-01', 304, 28, 77),
(9780140449150, 'The Prince', 'Uma análise das estratégias de conquista e manutenção do poder político.', '2003-01-01', 144, 28, 36),
(9780872201361, 'Republic', 'Diálogos investigam a justiça, a educação e as relações entre o indivíduo e a cidade.', '1992-01-01', 300, 50, 78),
(9780735211292, 'Atomic Habits', 'Uma abordagem prática apresenta formas de construir hábitos a partir de pequenas mudanças e do ambiente.', '2018-01-01', 320, 51, 79),
(9781400069286, 'The Power of Habit', 'Histórias e pesquisas examinam como hábitos surgem e como seus ciclos podem ser transformados.', '2012-01-01', '', 52, 23),
(9780374533557, 'Thinking, Fast and Slow', 'Experimentos sobre julgamento mostram como intuição e reflexão influenciam nossas decisões.', '2013-01-01', 512, 53, 32),
(9780062316097, 'Sapiens: A Brief History of Humankind', 'Uma síntese histórica acompanha o desenvolvimento das sociedades humanas e suas formas de cooperação.', '2015-01-01', 464, 54, 7),
(9780062464316, 'Homo Deus: A Brief History of Tomorrow', 'O autor discute como transformações científicas podem modificar os objetivos e os conflitos humanos.', '2017-01-01', 464, 54, 7),
(9780525512172, '21 Lessons for the 21st Century', 'Ensaios exploram desafios contemporâneos ligados à tecnologia, à política e à vida coletiva.', '2018-01-01', 400, 55, 7),
(9780553380163, 'A Brief History of Time', 'Uma introdução aos grandes problemas da cosmologia, incluindo o tempo, os buracos negros e a origem do universo.', '1998-01-01', 212, 42, 61),
(9780393315707, 'Guns, Germs, and Steel', 'O livro examina relações entre ambiente, produção de alimentos e diferenças históricas de poder entre sociedades.', '1999-01-01', '', 56, 80),
(9780393609394, 'Astrophysics for People in a Hurry', 'Conceitos centrais da astrofísica são apresentados em capítulos curtos para leitores não especialistas.', '2017-01-01', 224, 56, 81),
(9780199291151, 'The Selfish Gene', 'Uma discussão da evolução apresenta a perspectiva dos genes e suas implicações para comportamentos biológicos.', '2006-01-01', 360, 57, 50),
(9780062457714, 'The Subtle Art of Not Giving a F*ck', 'O autor propõe rever prioridades e aceitar limites como parte da construção de uma vida com sentido.', '2016-01-01', 224, 46, 82),
(9780307352156, 'Quiet: The Power of Introverts in a World That Can''t Stop Talking', 'Pesquisas e relatos exploram os talentos e os desafios de pessoas introvertidas em ambientes que privilegiam a extroversão.', '2013-01-01', 352, 39, 83),
(9780385349949, 'Lean In: Women, Work, and the Will to Lead', 'A autora discute barreiras profissionais enfrentadas por mulheres e caminhos para ampliar sua participação na liderança.', '2013-01-01', 240, 36, 84),
(9780385486804, 'Into the Wild', 'Uma investigação reconstrói a trajetória de um jovem que abandona a vida convencional e viaja até o Alasca.', '1997-01-01', 224, 58, 85),
(9780385494786, 'Into Thin Air', 'Um relato da expedição ao Everest que terminou em tragédia durante uma tempestade em 1996.', '1999-01-01', 368, 58, 85),
(9780316017923, 'Outliers: The Story of Success', 'Casos de sucesso são examinados a partir de oportunidades, contexto cultural e prática acumulada.', '2008-01-01', 320, 24, 86),
(9780316346627, 'The Tipping Point', 'O autor investiga como ideias e comportamentos se espalham e alcançam mudanças em larga escala.', '2002-01-01', 304, 59, 86),
(9780316010665, 'Blink: The Power of Thinking Without Thinking', 'Pesquisas sobre decisões rápidas revelam as forças e as limitações do julgamento intuitivo.', '2007-01-01', 296, 59, 86),
(9780393324815, 'Moneyball: The Art of Winning an Unfair Game', 'Uma equipe de beisebol recorre a análises estatísticas para competir com adversários de orçamento maior.', '2004-01-01', 320, 56, 87),
(9780393338690, 'The Big Short: Inside the Doomsday Machine', 'A narrativa acompanha investidores que perceberam fragilidades do mercado hipotecário antes da crise financeira.', '2011-01-01', 320, 56, 87),
(9780307588371, 'Gone Girl', 'O desaparecimento de uma mulher transforma seu casamento em uma disputa de versões e suspeitas.', '2012-01-01', 432, 39, 44),
(9780307454546, 'The Girl with the Dragon Tattoo', 'Um jornalista e uma hacker investigam o desaparecimento de uma jovem de uma família poderosa.', '2009-01-01', 672, 60, 88),
(9780307454553, 'The Girl Who Played with Fire', 'Lisbeth Salander se torna suspeita de crimes ligados a uma investigação sobre exploração sexual.', '2010-01-01', 752, 60, 88),
(9781594634024, 'The Girl on the Train', 'Uma passageira acredita ter visto uma pista importante sobre uma mulher desaparecida.', '2015-01-01', 336, 61, 62),
(9781250301697, 'The Silent Patient', 'Um terapeuta procura descobrir por que uma pintora deixou de falar após ser acusada de matar o marido.', '2019-01-01', 336, 62, 89),
(9780525559474, 'The Midnight Library', 'Uma mulher encontra uma biblioteca de vidas alternativas e reconsidera os caminhos que deixou de seguir.', '2020-01-01', 304, 63, 90),
(9780735219090, 'Where the Crawdads Sing', 'Uma jovem criada nos pântanos enfrenta o isolamento e a suspeita em torno de uma morte.', '2018-01-01', 384, 64, 91),
(9781501110368, 'It Ends with Us', 'Lily precisa confrontar padrões de violência e escolhas afetivas enquanto constrói uma vida independente.', '2016-01-01', 384, 65, 92),
(9781668001226, 'It Starts with Us', 'Lily e Atlas tentam retomar uma relação enquanto conciliam responsabilidades e os efeitos do passado.', '2022-01-01', 336, 65, 92),
(9781476753188, 'Ugly Love', 'Uma relação baseada em regras aparentemente simples expõe feridas que seus participantes tentavam esconder.', '2014-01-01', 336, 65, 92),
(9781501173219, 'The Seven Husbands of Evelyn Hugo', 'Uma estrela de cinema conta sua história a uma jornalista e revela escolhas escondidas por sua imagem pública.', '2017-01-01', 400, 65, 93),
(9781524798628, 'Daisy Jones & The Six', 'Depoimentos reconstroem a ascensão e a separação de uma banda marcada por criatividade e conflitos pessoais.', '2019-01-01', 368, 66, 93),
(9780593321201, 'Malibu Rising', 'A festa anual de quatro irmãos expõe tensões familiares e memórias de um passado compartilhado.', '2021-01-01', 384, 66, 93),
(9780930289232, 'Watchmen', 'Uma investigação sobre a morte de um antigo herói expõe conspirações e dilemas sobre poder e vigilância.', '1995-01-01', 416, 67, 94),
(9781401207526, 'Batman: Year One', 'Bruce Wayne inicia sua atuação como Batman enquanto James Gordon enfrenta a corrupção da polícia de Gotham.', '2005-01-01', 144, 67, 96),
(9781401238964, 'Batman: The Dark Knight Returns', 'Um Bruce Wayne envelhecido retorna às ruas e confronta as mudanças em Gotham e em sua própria identidade.', '2012-01-01', 224, 67, 96),
(9780394747231, 'Maus I: A Survivor''s Tale: My Father Bleeds History', 'Um autor registra as memórias do pai sobre a perseguição nazista e as dificuldades de transmitir essa experiência.', '1986-01-01', 160, 68, 100),
(9780679729778, 'Maus II: A Survivor''s Tale: And Here My Troubles Began', 'A continuação das memórias de sobrevivência aproxima o testemunho histórico dos conflitos entre pai e filho.', '1991-01-01', 144, 68, 100),
(9780375714573, 'Persepolis: The Story of a Childhood', 'Uma menina acompanha as transformações políticas do Irã enquanto tenta compreender a infância em meio à repressão e à guerra.', '2004-01-01', 160, 68, 101),
(9780375714832, 'Persepolis 2: The Story of a Return', 'A autora relata a adolescência no exterior e as dificuldades de retornar a um país transformado.', '2005-01-01', 192, 68, 101),
(9781891830853, 'Blankets', 'Memórias da juventude unem questões familiares, religião e a descoberta do primeiro amor.', '2003-01-01', 592, 69, 102),
(9781603090384, 'Essex County', 'Histórias de uma comunidade rural canadense revelam laços familiares, memórias e solidão.', '2009-01-01', 512, 69, 103),
(9781612620244, 'Attack on Titan 1', 'Jovens soldados enfrentam gigantes que ameaçam os muros onde os últimos humanos procuram proteção.', '2012-01-01', 208, 70, 104),
(9781421582696, 'My Hero Academia, Vol. 1', 'Um garoto sem poderes recebe a chance de estudar em uma escola de heróis e precisa descobrir o que significa salvar alguém.', '2015-01-01', 192, 71, 105),
(9781569319000, 'Naruto, Vol. 1', 'Um jovem ninja procura reconhecimento enquanto aprende a trabalhar em equipe e dominar suas habilidades.', '2003-01-01', 192, 71, 106),
(9781569319017, 'One Piece, Vol. 1', 'Luffy inicia uma viagem pelos mares em busca de uma tripulação e de um tesouro lendário.', '2003-01-01', 216, 71, 107),
(9781421501680, 'Death Note, Vol. 1', 'Um estudante encontra um caderno capaz de matar pessoas e passa a enfrentar um investigador determinado a detê-lo.', '2005-01-01', 200, 71, 108),
(9781421561325, 'Uzumaki', 'Uma cidade costeira é tomada por acontecimentos perturbadores associados à forma de uma espiral.', '2013-01-01', 648, 71, 110),
(9781591169208, 'Fullmetal Alchemist, Vol. 1', 'Dois irmãos alquimistas buscam reparar as consequências de uma tentativa proibida de trazer a mãe de volta à vida.', '2005-01-01', 192, 71, 111);

